mapper.select:
select id, house_id, cage_id, tag_uid, request_id, remark, create_by, create_time, update_by, update_time
from cage_nfc_tags
where house_id = #{houseId}
  and tag_uid = #{tagUid}
limit 1

select c.id, c.house_id, c.cage_number, c.status, c.rabbit_count, c.is_fed, c.is_enabled, c.remark, c.create_by, c.create_time, c.update_by, c.update_time
from cage_nfc_tags t
         join cages c on c.id = t.cage_id
where t.house_id = #{houseId}
  and t.tag_uid = #{tagUid}
limit 1

mapper.delete:
delete from cage_nfc_tags
where house_id = #{houseId}
  and tag_uid = #{tagUid}
